"""1590 (#102): Probe-StateTrigger-v1588.ps1 with -Midnight: during each trigger the role's midnight scene manager is
watched (probe --watch-midnight, read-only) from just before the input to the end of the settle time. The raw watch goes
to a temporary file outside the take; the take keeps trigger-N-midnight.json with the samples that hold player gadget,
power or Timepiece scenes (asset under midnight/gameplay/player/ or naming timeshift, or bound to a player channel) and
the row keeps a summary per asset (subscene, duration, first and last tick offset, highest clock word 1) and the
role's position before and after the trigger (a time shift moves it about 600 m in z). The role's
inventory is saved at the start (inventory-start.json). -KeepWorld skips the fixture restoration (the probe runs inside
a Route-Mission -HoldAtEnd hold, which Restore-RouteHold-v1303 restores afterwards). Generated by make_state_trigger_v1590.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Probe-StateTrigger-v1588.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("[string]$Candidate='candidate-npc-combat-v1214es')", "[string]$Candidate='candidate-npc-combat-v1214es',[switch]$Midnight,[switch]$KeepWorld)")
rep("  if($dirty){\n   $cw=[Diagnostics.Stopwatch]::StartNew()", "  if($dirty-and!$KeepWorld){\n   $cw=[Diagnostics.Stopwatch]::StartNew()")
first = s.index('\n') + 1
s = s[:first] + "# 1590 (#102): -Midnight watches the role's midnight scenes during each trigger. Generated by make_state_trigger_v1590.py.\n" + s[first:]
rep(" Save \"$out/identity.json\" @{candidate=$Candidate;dll=$pin.dll;role=$Role;triggers=$Triggers}\n",
    " Save \"$out/identity.json\" @{candidate=$Candidate;dll=$pin.dll;role=$Role;triggers=$Triggers;midnight=[bool]$Midnight}\n"
    " if($Midnight){Save \"$out/inventory-start.json\" (Q $Role '--player-inventory')}\n")
rep("  & \"$lab/Send-D2Input.ps1\" @ia|Out-Null;$w=[Diagnostics.Stopwatch]::StartNew()\n",
    "  $mid=$null;$midSum=$null;$mraw=Join-Path ([IO.Path]::GetTempPath()) \"d2-midnight-$Take-$($rows.Count+1).jsonl\"\n"
    "  if($Midnight){$mid=Start-Process -FilePath \"$lab/bin/d2_runtime_probe.exe\" -ArgumentList @(\"$($pids[$Role])\",'--watch-midnight',\"$([Math]::Min(32000,$ms+$SettleMs+400))\") -NoNewWindow -PassThru -RedirectStandardOutput $mraw -RedirectStandardError \"$mraw.err\";Start-Sleep -Milliseconds 200}\n"
    "  & \"$lab/Send-D2Input.ps1\" @ia|Out-Null;$w=[Diagnostics.Stopwatch]::StartNew()\n")
rep("  foreach($cpx in $caps){try{$cpx.WaitForExit(15000)|Out-Null}catch{}};",
    "  if($mid){try{$mid.WaitForExit(40000)|Out-Null}catch{};$msamples=[Collections.Generic.List[object]]::new();$msum=[ordered]@{};$t0=$null\n"
    "   foreach($ln in @(Get-Content -LiteralPath $mraw -ErrorAction SilentlyContinue)){$j=try{$ln|ConvertFrom-Json}catch{$null};if(!$j){continue};if($null-eq$t0){$t0=[int64]$j.tick}\n"
    "    $keep=@($j.instances|Where-Object {[string]$_.asset-match'midnight/gameplay/player/|timeshift'-or$_.playerChannel-ge0}|ForEach-Object {[ordered]@{id=$_.id;state=$_.state;playerChannel=$_.playerChannel;asset=$_.asset;subscene=$_.subscene;sceneDurationMs=$_.sceneDurationMs;clockWords=$_.clockWords;bindings=@($_.bindingsResearch).Count}})\n"
    "    if($keep.Count){$dt=[int64]$j.tick-$t0;$msamples.Add([ordered]@{ms=$dt;instances=$keep})\n"
    "     foreach($k in $keep){$key=\"$($k.asset)|$($k.subscene)\";if(!$msum.Contains($key)){$msum[$key]=[ordered]@{asset=$k.asset;subscene=$k.subscene;durationMs=$k.sceneDurationMs;state=$k.state;playerChannel=$k.playerChannel;bindings=$k.bindings;firstMs=$dt;lastMs=$dt;maxClock1=0}}\n"
    "      $e=$msum[$key];$e.lastMs=$dt;if(@($k.clockWords).Count-gt1-and[int64]$k.clockWords[1]-gt$e.maxClock1){$e.maxClock1=[int64]$k.clockWords[1]}}}}\n"
    "   Save \"$out/trigger-$($rows.Count+1)-midnight.json\" @($msamples);$midSum=@($msum.Values);Remove-Item -LiteralPath $mraw,\"$mraw.err\" -ErrorAction SilentlyContinue}\n"
    "  foreach($cpx in $caps){try{$cpx.WaitForExit(15000)|Out-Null}catch{}};")
rep("closedWithB=$closed;logicAfter=$logic})", "closedWithB=$closed;logicAfter=$logic;midnight=$midSum;posBefore=$posB;posAfter=$(try{(Q $Role '--player').candidatePosition}catch{$null})})")
rep("  $before=@((Q $Role '--player-states').active|ForEach-Object {\"$($_.id):$($_.type)\"});",
    "  $posB=try{(Q $Role '--player').candidatePosition}catch{$null};$before=@((Q $Role '--player-states').active|ForEach-Object {\"$($_.id):$($_.type)\"});")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Probe-StateTrigger-v1590.ps1').write_bytes(out.encode('utf-8'))
print('ok')
